INSERT INTO courses (id, title, segment, featured, coming_soon, hidden, duration, modality, img, short, for_who, learn, syllabus, sort_order) VALUES ('eletricista-predial-residencial', 'Eletricista Predial e Residencial', 'energia-eletrica', 1, 0, 0, '60h', 'presencial', 'eletricista-predial', 'Aprenda na prática como instalar, manter e reparar sistemas elétricos em casas, apartamentos e prédios, seguindo todas as normas de segurança.', 'Iniciantes que querem começar do zero, profissionais que buscam se especializar e quem procura uma nova fonte de renda.', '["Fundamentos da eletricidade: corrente, tensão, resistência e potência","Segurança em instalações elétricas (NR-10) e uso de EPIs","Leitura de diagramas e simbologia elétrica","Instalação elétrica residencial e predial","Manutenção, reparo e eficiência energética"]', '["Fundamentos da eletricidade","Segurança em instalações elétricas (NR-10)","Leitura de diagramas elétricos","Instalação elétrica residencial","Instalação elétrica predial","Manutenção e reparo elétrico","Eficiência energética","Normas e regulamentações elétricas"]', 0);
INSERT INTO courses (id, title, segment, featured, coming_soon, hidden, duration, modality, img, short, for_who, learn, syllabus, sort_order) VALUES ('comandos-eletricos', 'Eletricista Força e Controle', 'energia-eletrica', 1, 0, 0, '60h', 'presencial', 'comandos-eletricos', 'Ideal para quem deseja atuar na área industrial, aprendendo na prática a instalação, manutenção e comando de motores elétricos e sistemas automatizados.', 'Eletricistas que querem entrar ou se especializar na área industrial, técnicos de manutenção e quem busca uma profissão com alta empregabilidade.', '["Fundamentos de eletricidade aplicada à indústria","Segurança em instalações elétricas (NR-10) em ambientes industriais","Leitura e interpretação de diagramas de força e controle","Comandos elétricos: partida direta, reversão e intertravamentos","Montagem de painéis e manutenção elétrica industrial"]', '["Fundamentos da eletricidade aplicada","Segurança em instalações elétricas (NR-10)","Leitura e interpretação de diagramas elétricos","Comandos elétricos","Dispositivos elétricos industriais","Montagem de painéis elétricos","Motores elétricos","Manutenção elétrica industrial"]', 1);
INSERT INTO courses (id, title, segment, featured, coming_soon, hidden, duration, modality, img, short, for_who, learn, syllabus, sort_order) VALUES ('redes-distribuicao', 'Eletricista Redes de Distribuição', 'energia-eletrica', 0, 0, 0, '240h', 'ead', 'redes-distribuicao', 'Curso 100% online para quem deseja adquirir conhecimento técnico sobre o funcionamento das redes de distribuição de energia elétrica.', 'Quem deseja atuar em concessionárias como Enel e Light, em empresas terceirizadas, ou construir uma base teórica sólida no setor elétrico.', '["Fundamentos de eletricidade aplicados às redes (tensão, corrente, resistência e potência)","Redes de baixa e média tensão: conceitos e aplicações","Componentes das redes: postes, isoladores, transformadores e condutores","Sistema de medição e princípios de transformadores","Identificação e análise de falhas em redes energizadas"]', '["Introdução à eletricidade aplicada às redes","Redes de distribuição de energia elétrica","Componentes das redes elétricas","Montagem de redes aéreas (conceitos)","Manutenção de redes de distribuição","Sistema de medição e transformadores","Cálculo de demanda e carga elétrica","Operação em redes energizadas (teoria)","Identificação e análise de falhas","Funcionamento das concessionárias e boas práticas"]', 2);
INSERT INTO courses (id, title, segment, featured, coming_soon, hidden, duration, modality, img, short, for_who, learn, syllabus, sort_order) VALUES ('energia-solar-fotovoltaica', 'Qualificação Instalação Energia Solar', 'energia-eletrica', 1, 0, 0, '32h', 'presencial', 'energia-solar', 'Aprenda a instalar, projetar e manter sistemas de energia solar com foco em aplicações residenciais e comerciais.', 'Eletricistas e empreendedores que querem entrar no mercado de energia solar, um dos setores que mais cresce no Brasil.', '["Painéis fotovoltaicos, coletores solares e sistemas de armazenamento","Sistemas conectados à rede (grid-tied) e autônomos (off-grid)","Projeto e dimensionamento: avaliação do local, carga e sombreamento","Instalação segura, testes e comissionamento","Normas, conexão à rede e procedimentos de licenciamento","Bônus inclusos: NR-10 e NR-35 (EAD) + mentoria de carreira"]', '["Introdução à energia solar","Tecnologias de energia solar (fotovoltaico e térmico)","Sistemas grid-tied e off-grid","Projeto e dimensionamento de sistemas solares","Instalação e manutenção","Aplicações avançadas e tendências do mercado","Aspectos técnicos e regulatórios"]', 3);
INSERT INTO courses (id, title, segment, featured, coming_soon, hidden, duration, modality, img, short, for_who, learn, syllabus, sort_order) VALUES ('ar-condicionado', 'Ar Condicionado Split + Inverter', 'refrigeracao', 1, 0, 0, '60h', 'presencial', 'refrigeracao', 'Instalação e manutenção de ar-condicionado split convencional e inverter — uma das áreas mais promissoras do mercado.', 'Iniciantes que querem aprender uma profissão técnica, profissionais que já atuam com ar-condicionado, técnicos que querem se atualizar em inverter e quem busca renda extra ou quer trabalhar de forma autônoma.', '["Diferenças entre sistemas split convencional e inverter","Componentes: unidade interna/externa, compressor, placas e sensores","Instalação de split convencional e inverter (tubulação, dreno, ligação elétrica)","Vácuo e carga de gás refrigerante","Manutenção preventiva e corretiva com diagnóstico de falhas"]', '["Fundamentos da refrigeração","Tipos de ar condicionado split","Componentes dos sistemas","Ferramentas e equipamentos","Instalação de split convencional","Instalação de split inverter","Vácuo e carga de gás refrigerante","Manutenção preventiva","Manutenção corretiva","Testes e funcionamento"]', 4);
INSERT INTO courses (id, title, segment, featured, coming_soon, hidden, duration, modality, img, short, for_who, learn, syllabus, sort_order) VALUES ('seguranca-eletronica-cftv', 'CFTV e Monitoramento Inteligente', 'seguranca-eletronica', 1, 0, 0, '60h', 'presencial', 'seguranca-eletronica', 'Projete, instale e configure sistemas avançados de vigilância por vídeo, com câmeras analógicas e IP, DVR/NVR, acesso remoto e integração com interfonia e controle de acesso.', 'Quem quer trabalhar como instalador de câmeras de segurança (CFTV) ou empreender com instalação e manutenção na área.', '["Instalação de câmeras: do zero ao avançado, MultiHD e sistemas IP","Configuração avançada de DVR/NVR: gravação inteligente, detecção de eventos e mascaramento de privacidade","Configuração em rede: IP, máscaras, gateway, DNS e redirecionamento de portas","Acesso remoto via QR Code e DDNS próprio para visualização em tempo real","Bônus incluso: NR-10"]', '["Instalação de câmeras de vigilância","Configuração do DVR/NVR","Configuração em rede","Acesso remoto"]', 5);
INSERT INTO courses (id, title, segment, featured, coming_soon, hidden, duration, modality, img, short, for_who, learn, syllabus, sort_order) VALUES ('automacao-residencial', 'Automação Residencial', 'seguranca-eletronica', 0, 0, 0, '20h', 'presencial', 'automacao-residencial', 'Transforme qualquer casa em uma casa inteligente com os dispositivos Wi-Fi da linha Izy Intelbras — tomadas, interruptores e integração com a Alexa.', 'Eletricistas e instaladores que querem agregar um serviço de automação residencial (casa inteligente) rentável e de rápida execução.', '["Conceito de casa inteligente e dispositivos Wi-Fi Intelbras (linha Izy)","Instalação e configuração de tomadas inteligentes","Instalação e configuração de interruptores inteligentes","Cenários e rotinas programáveis para iluminação e eletrodomésticos","Integração com a Alexa e controle por comando de voz","Controle remoto pelo aplicativo, de onde estiver","Bônus incluso: NR-10"]', '["Introdução à casa inteligente e automação residencial","Linha Izy Intelbras: dispositivos e configuração via Wi-Fi","Tomadas e interruptores inteligentes","Cenários e rotinas de automação","Integração com Alexa e assistentes de voz"]', 6);
INSERT INTO courses (id, title, segment, featured, coming_soon, hidden, duration, modality, img, short, for_who, learn, syllabus, sort_order) VALUES ('eletricista-naval', 'Eletricista Naval', 'naval-offshore', 1, 0, 0, '80h', 'presencial', 'eletricista-naval', 'Aprenda os fundamentos dos sistemas elétricos em embarcações e adquira habilidades práticas em instalação, manutenção e reparo de equipamentos elétricos marítimos.', 'Profissionais interessados em ingressar na indústria naval ou eletricistas em busca de especialização, para atuar em estaleiros, navios ou plataformas offshore.', '["Comandos elétricos: componentes, diagramas de força e controle","Diagrama unifilar e princípios de controle de motores","Estrutura naval e infraestrutura elétrica de embarcações","Lançamento de cabos, fixação de equipamentos e caminho mecânico","Reparo naval: diagnóstico e correção de falhas elétricas"]', '["Introdução aos comandos elétricos","Componentes de comandos elétricos","Diagramas de comandos elétricos","Princípios de controle","Diagrama unifilar","Estrutura naval","Infraestrutura elétrica","Reparo naval","Prática em laboratório","Emprego e apoio à empregabilidade"]', 7);
INSERT INTO courses (id, title, segment, featured, coming_soon, hidden, duration, modality, img, short, for_who, learn, syllabus, sort_order) VALUES ('drywall', 'Instalador de Drywall', 'construcao-civil', 0, 0, 0, '32h', 'presencial', 'drywall', 'Aprenda na prática a montagem de paredes, forros e revestimentos em drywall — construção a seco, mais rápida, limpa e com excelentes oportunidades de ganho.', 'Pedreiros, gesseiros, pintores e profissionais de reforma que querem se modernizar na construção a seco, ou quem busca uma nova profissão com retorno financeiro rápido.', '["Sistema de construção a seco: tipos de chapas (ST, RU, RF) e vantagens sobre a alvenaria","Ferramental específico e uso correto de EPIs","Marcação e estruturação metálica com nível laser","Chapeamento, corte, parafusamento e reforços estruturais","Forros, revestimentos e acabamento de juntas com fita e massa"]', '["Introdução ao sistema de construção a seco","Ferramental e segurança no trabalho","Marcação e estruturação metálica","Chapeamento e reforços estruturais","Forros, revestimentos e acabamento final"]', 8);
INSERT INTO courses (id, title, segment, featured, coming_soon, hidden, duration, modality, img, short, for_who, learn, syllabus, sort_order) VALUES ('pintor-residencial', 'Pintor Residencial', 'construcao-civil', 0, 1, 0, NULL, NULL, 'pintor-residencial', 'Técnicas de pintura residencial profissional — preparo de superfícies, texturas e acabamento de alto padrão.', '', '[]', '[]', 9);
INSERT INTO courses (id, title, segment, featured, coming_soon, hidden, duration, modality, img, short, for_who, learn, syllabus, sort_order) VALUES ('rotinas-administrativas', 'Assistente Administrativo', 'administrativo', 0, 0, 0, '40h', 'presencial', 'administrativo', 'Desenvolva as competências para atuar no apoio administrativo de uma empresa: rotina de pessoal, documentos, atendimento e movimentação de bens e serviços.', 'Quem busca o primeiro emprego ou recolocação na área administrativa, atuando como apoio operacional em diversas áreas da organização.', '["Gestão de documentos e organização de arquivos","Comunicação profissional e atendimento ao cliente","Suporte administrativo e gestão de tempo e agenda","Tarefas financeiras básicas e uso de tecnologia de escritório","Organização de eventos, gestão de suprimentos e confidencialidade"]', '["Gestão de documentos","Comunicação e atendimento ao cliente","Suporte administrativo","Gestão de tempo e agenda","Tarefas financeiras básicas","Uso de tecnologia de escritório","Organização de eventos e gestão de suprimentos","Confidencialidade, ética e colaboração em equipe"]', 10);
INSERT INTO courses (id, title, segment, featured, coming_soon, hidden, duration, modality, img, short, for_who, learn, syllabus, sort_order) VALUES ('nr-10', 'NR-10 — Segurança em Instalações Elétricas', 'nr-seguranca', 1, 0, 0, NULL, NULL, 'nr10', 'Certificação obrigatória para trabalhar com eletricidade com segurança conforme a norma.', 'Eletricistas e profissionais que atuam ou vão atuar com instalações elétricas.', '["Riscos elétricos e medidas de controle","Procedimentos de trabalho seguro","Equipamentos de proteção coletiva e individual","Responsabilidades e documentação","Primeiros socorros e emergências"]', '["Introdução à NR-10","Riscos e proteção","Procedimentos seguros","Documentação e responsabilidades","Avaliação e certificação"]', 11);
INSERT INTO courses (id, title, segment, featured, coming_soon, hidden, duration, modality, img, short, for_who, learn, syllabus, sort_order) VALUES ('nr-33', 'NR-33 — Espaços Confinados', 'nr-seguranca', 0, 0, 0, NULL, NULL, 'nr33', 'Capacitação para trabalho seguro em espaços confinados, exigência de muitas indústrias.', 'Trabalhadores e supervisores que atuam em espaços confinados.', '["Identificação de espaços confinados","Riscos e monitoramento atmosférico","Permissão de entrada e trabalho","Equipamentos e resgate","Procedimentos de emergência"]', '["Conceitos da NR-33","Riscos e atmosfera","Permissão de entrada","Equipamentos e resgate","Avaliação"]', 12);
INSERT INTO courses (id, title, segment, featured, coming_soon, hidden, duration, modality, img, short, for_who, learn, syllabus, sort_order) VALUES ('nr-34', 'NR-34 — Construção e Reparação Naval', 'nr-seguranca', 0, 0, 0, NULL, NULL, 'nr34', 'Segurança do trabalho na indústria naval, essencial para estaleiros do Rio de Janeiro.', 'Profissionais que atuam em estaleiros e reparação naval.', '["Riscos da atividade naval","Trabalho a quente e em altura","Sinalização e permissões","Equipamentos de proteção","Procedimentos e responsabilidades"]', '["Introdução à NR-34","Riscos do setor naval","Trabalho a quente e altura","Permissões e sinalização","Avaliação"]', 13);
INSERT INTO courses (id, title, segment, featured, coming_soon, hidden, duration, modality, img, short, for_who, learn, syllabus, sort_order) VALUES ('nr-35', 'NR-35 — Trabalho em Altura', 'nr-seguranca', 1, 0, 0, NULL, NULL, 'nr35', 'Certificação para atividades acima de 2 metros com segurança e conforme a norma.', 'Todo profissional que executa trabalho em altura em qualquer setor.', '["Análise de risco e planejamento","Sistemas de proteção contra quedas","Uso de cinturão, trava-quedas e ancoragem","Procedimentos de resgate","Responsabilidades e documentação"]', '["Conceitos da NR-35","Análise de risco","Equipamentos de proteção","Práticas seguras","Resgate e avaliação"]', 14);
INSERT INTO courses (id, title, segment, featured, coming_soon, hidden, duration, modality, img, short, for_who, learn, syllabus, sort_order) VALUES ('eletronica-basica', 'Eletrônica Básica', 'energia-eletrica', 0, 0, 0, '40h', 'presencial', 'eletronica-basica', 'Conheça e identifique componentes eletrônicos básicos, além de aplicá-los em circuitos eletrônicos de menor complexidade.', 'Quem quer iniciar na eletrônica e criar base sólida para elétrica, automação e manutenção de equipamentos.', '["Grandezas elétricas: tensão, corrente e resistência","Componentes: resistores, capacitores, diodos e transistores","Leitura de esquemas e uso do multímetro","Montagem de circuitos em protoboard","Solda eletrônica e boas práticas"]', '["Fundamentos de eletricidade e eletrônica","Componentes passivos e ativos","Instrumentos de medição","Circuitos práticos em bancada","Diagnóstico e manutenção básica"]', 15);
INSERT INTO courses (id, title, segment, featured, coming_soon, hidden, duration, modality, img, short, for_who, learn, syllabus, sort_order) VALUES ('inversor-frequencia', 'Soft Starter e Inversor de Frequência', 'energia-eletrica', 0, 0, 0, '40h', 'presencial', 'inversor-frequencia', 'Conheça os dispositivos essenciais para proteger motores e reduzir custos de energia com partida em rampa — soft starter e inversor de frequência.', 'Eletricistas e profissionais de manutenção industrial que querem trabalhar com acionamento de motores.', '["Princípios de funcionamento do inversor","Parametrização e configuração","Controle de velocidade e rampas de aceleração","Proteções e diagnóstico de falhas","Aplicações industriais reais","Bônus inclusos: treinamento de NRs e mentoria de carreira"]', '["Motores elétricos e acionamentos","Introdução ao inversor de frequência","Parâmetros essenciais","Ligações e comando","Prática de configuração e testes"]', 16);
INSERT INTO courses (id, title, segment, featured, coming_soon, hidden, duration, modality, img, short, for_who, learn, syllabus, sort_order) VALUES ('carregador-veicular', 'Carregador Elétrico Veicular', 'energia-eletrica', 0, 0, 0, '24h', 'presencial', 'carregador-veicular', 'Capacite-se para a mobilidade sustentável aprendendo sobre instalação e manutenção de infraestruturas de carregamento elétrico.', 'Eletricistas, técnicos automotivos e entusiastas da tecnologia que querem atuar na mobilidade elétrica.', '["Fundamentos de veículos elétricos: baterias, motores e tecnologias de carregamento","Infraestrutura: carregadores residenciais, comerciais e públicos","Normas e regulamentações de segurança para instalação","Projeto, dimensionamento e instalação de sistemas de carregamento","Manutenção preventiva, corretiva e diagnóstico de falhas"]', '["Introdução aos veículos elétricos","Infraestrutura de carregamento","Normas e regulamentações","Projeto e instalação","Manutenção e diagnóstico de problemas","Tecnologias emergentes e tendências","Prática em laboratório"]', 17);
INSERT INTO courses (id, title, segment, featured, coming_soon, hidden, duration, modality, img, short, for_who, learn, syllabus, sort_order) VALUES ('clp', 'CLP — Controlador Lógico Programável', 'energia-eletrica', 0, 1, 0, NULL, NULL, NULL, 'Programação e automação industrial com CLP — em breve na Upjobs.', '', '[]', '[]', 18);
INSERT INTO courses (id, title, segment, featured, coming_soon, hidden, duration, modality, img, short, for_who, learn, syllabus, sort_order) VALUES ('refrigeracao-domiciliar', 'Refrigeração Domiciliar', 'refrigeracao', 0, 0, 0, '40h', 'presencial', 'refrigeracao-domiciliar', 'Aprenda a instalar, manter e consertar geladeiras, freezers, frigobares e ar-condicionado de janela — do princípio da refrigeração ao atendimento ao cliente.', 'Quem quer se tornar técnico em refrigeração residencial, atuar por conta própria ou como funcionário, e oferecer serviços de manutenção de qualidade.', '["Princípios de refrigeração e ciclo de compressão de vapor","Componentes: compressor, condensador, evaporador e válvula de expansão","Sistemas residenciais: geladeiras, freezers, split, janela e portáteis","Instalação, manutenção preventiva e resolução de problemas","Eficiência energética, normas de segurança e atendimento ao cliente","Bônus incluso: NR-10 (segurança em instalações elétricas)"]', '["Princípios de refrigeração","Componentes do sistema de refrigeração","Tipos de sistemas de refrigeração residencial","Instalação e manutenção de equipamentos","Eficiência energética e sustentabilidade","Normas de segurança e legislação","Tecnologias emergentes","Atendimento ao cliente e boas práticas profissionais"]', 19);
INSERT INTO courses (id, title, segment, featured, coming_soon, hidden, duration, modality, img, short, for_who, learn, syllabus, sort_order) VALUES ('refrigeracao-comercial-industrial', 'Refrigeração Comercial e Industrial', 'refrigeracao', 0, 0, 0, NULL, NULL, 'refrigeracao-comercial-industrial', 'Instalação e manutenção de câmaras frigoríficas e balcões refrigerados para comércios e indústrias.', 'Quem quer atuar em supermercados, açougues, restaurantes e indústrias que dependem de refrigeração o ano todo.', '["Sistemas de refrigeração comercial e industrial","Câmaras frigoríficas e balcões refrigerados","Compressores, condensadores e evaporadores de maior porte","Carga de gás e manutenção de sistemas comerciais","Diagnóstico de falhas e manutenção preventiva"]', '["Fundamentos da refrigeração comercial","Equipamentos e componentes de maior porte","Instalação de câmaras e balcões refrigerados","Manutenção e recarga de sistemas comerciais","Diagnóstico de falhas na prática"]', 20);
INSERT INTO courses (id, title, segment, featured, coming_soon, hidden, duration, modality, img, short, for_who, learn, syllabus, sort_order) VALUES ('maquina-lavar', 'Máquina de Lavar', 'refrigeracao', 0, 0, 0, NULL, NULL, 'maquina-lavar', 'Aprenda manutenção e conserto de lavadoras na prática. Transforme conhecimento em renda rápida.', 'Quem busca uma renda extra ou uma profissão como técnico em manutenção de eletrodomésticos.', '["Funcionamento mecânico e elétrico das lavadoras","Placas eletrônicas e sensores","Troca de rolamentos, correias e motores","Diagnóstico de defeitos comuns","Atendimento e orçamento ao cliente"]', '["Tipos de lavadoras e componentes","Sistema elétrico e eletrônico","Desmontagem e montagem","Diagnóstico de falhas","Reparos práticos"]', 21);
INSERT INTO courses (id, title, segment, featured, coming_soon, hidden, duration, modality, img, short, for_who, learn, syllabus, sort_order) VALUES ('soldador', 'Soldador', 'naval-offshore', 0, 0, 0, '30 a 60h', 'presencial', 'soldador', 'Formação teórica e prática completa em soldagem para atuar na indústria metalúrgica, construção civil e nos setores Naval e Offshore.', 'Quem quer atuar como soldador na indústria metalúrgica, construção civil, Naval e Offshore, capacitando-se em eletrodo revestido, MIG/MAG, TIG e arame tubular.', '["Fundamentos da soldagem, EPIs/EPCs e leitura de símbolos e desenhos","Solda com eletrodo revestido: seleção, regulagem e execução de cordões","Solda MIG/MAG: arames, gases e prática em aço carbono","Solda TIG: tungstênio, gases e acabamento de precisão em aço carbono e inox","Solda com arame tubular: regulagem e execução em chapas estruturais","Inspeção básica de juntas soldadas e prevenção de defeitos","Bônus incluso: NRs"]', '["Introdução à soldagem","Solda com eletrodo revestido","Solda MIG/MAG","Solda TIG","Solda com arame tubular","Encerramento e avaliação prática"]', 22);
INSERT INTO courses (id, title, segment, featured, coming_soon, hidden, duration, modality, img, short, for_who, learn, syllabus, sort_order) VALUES ('mecanico-diesel', 'Mecânico Diesel Naval e Industrial', 'naval-offshore', 0, 0, 0, '40h', 'presencial', 'mecanico-diesel', 'Aprenda a manutenção, reparo e operação de motores diesel navais e industriais — sistemas de propulsão, geração de energia e diagnóstico de falhas.', 'Profissionais da indústria naval, técnicos de manutenção industrial, engenheiros mecânicos e entusiastas de motores em busca de especialização.', '["Princípios de funcionamento e ciclo de trabalho de motores diesel","Mecânica naval e industrial: tipos de motores e particularidades de manutenção","Manutenção preventiva e corretiva, diagnóstico de falhas","Sistemas de propulsão naval e geradores de energia","Procedimentos de montagem, desmontagem e metrologia aplicada","Normas de segurança e regulamentações para ambientes marítimos e industriais"]', '["Introdução aos motores diesel","Mecânica naval e industrial","Manutenção preventiva e corretiva","Sistemas de propulsão e geração de energia","Segurança e regulamentações","Procedimento de montagem e desmontagem","Funcionamento e diagnóstico de falhas","Treinamento prático (hands-on)","Metrologia"]', 23);
INSERT INTO courses (id, title, segment, featured, coming_soon, hidden, duration, modality, img, short, for_who, learn, syllabus, sort_order) VALUES ('metrologia', 'Metrologia', 'naval-offshore', 0, 0, 0, '16h', 'semipresencial', 'metrologia', 'Domine os princípios da medição e controle de qualidade em processos industriais, operando e calibrando instrumentos como micrômetros, paquímetros e medidores de altura.', 'Profissionais que desejam atuar na área de qualidade, engenheiros, técnicos e estudantes que buscam especialização em metrologia industrial.', '["Conceitos fundamentais de metrologia e aplicações no controle de qualidade","Normas gerais de medição e padronização industrial","Múltiplos e submúltiplos das unidades de medida","Operação, calibração e interpretação de micrômetros, paquímetros e medidores digitais","Bônus incluso: NR-10 e NR-35"]', '["Introdução à metrologia","Normas gerais de medição","Múltiplos e submúltiplos","Princípios de instrumentos de medição","Prática em laboratório"]', 24);
INSERT INTO courses (id, title, segment, featured, coming_soon, hidden, duration, modality, img, short, for_who, learn, syllabus, sort_order) VALUES ('estruturas-navais', 'Estruturas Navais', 'naval-offshore', 0, 1, 0, NULL, NULL, NULL, 'Curso 100% EAD sobre estruturas e construção naval — em breve na Upjobs.', '', '[]', '[]', 25);
INSERT INTO courses (id, title, segment, featured, coming_soon, hidden, duration, modality, img, short, for_who, learn, syllabus, sort_order) VALUES ('assistente-dp-rh', 'Assistente de DP e RH', 'administrativo', 0, 0, 0, NULL, NULL, 'assistente-administrativo', 'Atue nos processos de rotinas trabalhistas, folha de pagamento e legislação.', 'Quem quer ingressar na área de Departamento Pessoal e Recursos Humanos.', '["Admissão e demissão de funcionários","Folha de pagamento e encargos","Rotinas trabalhistas e eSocial","Legislação trabalhista (CLT)","Benefícios e controle de ponto"]', '["Introdução ao DP e RH","Admissão e documentação","Folha de pagamento","Rotinas e obrigações legais","Rescisão e práticas"]', 26);
INSERT INTO courses (id, title, segment, featured, coming_soon, hidden, duration, modality, img, short, for_who, learn, syllabus, sort_order) VALUES ('atendente-farmacia', 'Atendente de Farmácia', 'administrativo', 0, 0, 0, NULL, NULL, 'atendente-farmacia', 'Capacitação para atuação na dispensação de medicamentos e atendimento técnico em farmácias.', 'Quem deseja trabalhar em farmácias e drogarias com atendimento e vendas.', '["Noções de farmacologia","Dispensação de medicamentos","Atendimento e vendas","Controle de estoque e validade","Legislação sanitária"]', '["Introdução ao setor farmacêutico","Medicamentos e classificação","Atendimento ao cliente","Estoque e organização","Rotinas e legislação"]', 27);
INSERT INTO courses (id, title, segment, featured, coming_soon, hidden, duration, modality, img, short, for_who, learn, syllabus, sort_order) VALUES ('deteccao-alarme-incendio', 'Sistemas de Detecção e Alarme de Incêndio', 'seguranca-eletronica', 0, 0, 0, '60h', 'presencial', 'alarme-incendio', 'Projete, instale e comissione sistemas automáticos de detecção e alarme de incêndio, com interface a sistemas de combate e supervisão predial.', 'Profissionais da área de combate a incêndio que querem se especializar na instalação e programação de centrais de alarme de incêndio.', '["Fundamentos de sistemas de detecção e alarme de incêndio","Instalação e programação da central de alarme","Interface com sistemas de combate a incêndio e supervisão predial","Normas aplicáveis: NR-23, ABNT NBR/ISO 7240, NBR IEC 60839, NBR 12693 e NBR 13434","Boas práticas para maximizar a segurança do sistema"]', '["Introdução aos sistemas de detecção e alarme de incêndio","Componentes e projeto básico do sistema","Instalação e programação da central de alarme","Interface com sistemas de combate e supervisão predial","Normas técnicas aplicáveis e boas práticas"]', 28);
